 const pts=a=>a.map(p=>p.map(Math.round).join(',')).join(' '),A=[13,76],B=[65,22],C=[160,45],D=[119,103],at=(u,v)=>[A[0]*(1-u)*(1-v)+B[0]*u*(1-v)+C[0]*u*v+D[0]*(1-u)*v,A[1]*(1-u)*(1-v)+B[1]*u*(1-v)+C[1]*u*v+D[1]*(1-u)*v];
