 const addedShield=Math.round(b.stats.def*(skill.shield||0));b.shield+=addedShield;
 b.enemyDef=Math.round(b.enemyDef*(1-(skill.break||0)));b.enemyClock+=(skill.delay||0)*1000/Math.max(1,b.monster.spd);
